/** Quick lookup: get all panels for a given row organ */
export function getPanelsForOrgan(rowIndex) {
  const row = ORGAN_NARRATIVES.find(r => r.rowIndex === rowIndex);
  return row ? row.panels : [];
}

/** Quick lookup: get a specific panel */
export function getPanel(rowIndex, colIndex) {
  const panels = getPanelsForOrgan(rowIndex);
  return panels.find(p => p.colIndex === colIndex) || null;
}

