export function getAllMythicNames() {
  const names = [];
  for (const row of ORGAN_NARRATIVES) {
    if (!row.complete) continue;
    for (const panel of row.panels) {
      names.push({
        rowOrgan: row.rowOrgan,
        colOrgan: panel.colOrgan,
        mythicName: panel.mythicName,
        tier: panel.tier,
      });
    }
  }
  return names;
}
